"""The decision is computed in code from per-criterion results, never generated by the model.

The model's job is narrower and checkable: judge each criterion and quote the evidence. Keeping the
final call deterministic makes it auditable and impossible to talk out of through injected text.
"""

from __future__ import annotations

from priorauth.schemas import CriterionResult, CriterionStatus, Decision, Policy


def decide(policy: Policy, results: list[CriterionResult]) -> Decision:
    by_id = {r.criterion_id: r.status for r in results}
    required = [c.criterion_id for c in policy.criteria if c.required]

    missing = [cid for cid in required if cid not in by_id]
    if missing:  # the matcher skipped a required criterion: never assume it is met
        return Decision.ESCALATE

    statuses = [by_id[cid] for cid in required]
    if any(s is CriterionStatus.NOT_MET for s in statuses):
        return Decision.ESCALATE
    if any(s is CriterionStatus.INSUFFICIENT_EVIDENCE for s in statuses):
        return Decision.NEEDS_DOCUMENTATION
    return Decision.READY_TO_SUBMIT
